[
  {
    "statement": "Evidence summaries report effects on farmland birds but do not provide cost information.",
    "citations": []
  },
  {
    "statement": "Nine studies from France, Sweden, and the UK found that providing supplementary food increased farmland bird abundance, breeding population size and density, body mass, hatching, nestling growth, and fledging rates.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Providing supplementary food increased the overwinter survival of a declining house sparrow population.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Fed male hen harriers bred with more females than control group hen harriers.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five replicated studies from the UK found no clear effects of providing supplementary food on breeding abundance, European turtle dove reproductive success, territory size or density, or the abundance of weed seeds.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five replicated studies from the UK found no clear effects of supplementary food on the overwinter survival of three stable house sparrow populations or on tree sparrow nest box use.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "One Swedish replicated, controlled study found providing supplementary food had no effect on clutch size or nestling weight and resulted in lower fledging rates in one year.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "The use of supplementary food by birds varied by species, region, season, and proximity to other food sources.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "For sowing wild bird seed or cover mixtures, a synthesis of 30 studies found that 21 of the studies showed positive effects.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "UK studies reported higher bird abundance, density, species diversity, and richness in wild bird cover than in other farmland habitats.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "UK studies reported that birds preferred and used wild bird cover more than other habitats.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "One review reported substantial grey partridge increases on farms with conservation measures that included cover crops.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Nine replicated studies from France and the UK reported that sowing wild bird seed or cover mixtures had mixed or negative effects compared to other habitats.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Additional UK studies on wild bird seed plots reported higher butterfly abundance or richness than some crops or grasslands.",
    "citations": [
      "3930",
      "594"
    ]
  },
  {
    "statement": "UK studies on wild bird seed plots reported mixed results for other invertebrates, indicating broader habitat influences associated with these mixtures.",
    "citations": [
      "3930",
      "594"
    ]
  }
]

[
  {
    "statement": "A review of studies from Canada, the USA, and the UK found increased predator numbers in crops adjacent to beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study reported the effects of beetle banks on predator numbers varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that beetle banks had no effect on predator numbers.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Two studies recorded small or slow movement of predators from beetle banks into crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that greater beetle activity in fields did not improve pest predation.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Four studies and a review recorded more invertebrate predators on beetle banks themselves than in surrounding crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "When comparing beetle banks to other refuge habitats in the UK and USA, two studies found more natural enemies on beetle banks, with one study noting the effect was seasonal.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "When comparing beetle banks to other refuge habitats, one review found similar or higher numbers of natural enemies.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "When comparing beetle banks to other refuge habitats, four studies found similar or lower numbers of natural enemies.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "A replicated, randomized study and a review found the largest pest reductions occurred closest to or on beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One review found fewer pests in fields with beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "The set of crops studied in relation to beetle banks included soybean, barley, field bean, maize, oats, pea, radish, rapeseed, wheat, and pasture.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Additional evidence, primarily from Denmark and the UK, reported positive effects from beetle banks on invertebrate densities or diversity in some seasons.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "The effects of beetle banks on invertebrates varied by the species of grass sown on the banks.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "The effects of beetle banks differed among various invertebrate groups.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Several studies found lower or no differences in invertebrate populations on beetle banks when compared to other habitats.",
    "citations": [
      "651"
    ]
  }
]

[
  {
    "statement": "No studies were found that directly tested marking fencing to avoid bird mortality on farmland wildlife.",
    "citations": [
      "706"
    ]
  },
  {
    "statement": "One randomised, replicated, controlled UK study reported fewer bird collisions with deer fences when sections were marked with orange netting compared to unmarked sections.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "No studies were found that directly tested avoiding the use of lead shot on farmland wildlife.",
    "citations": [
      "100"
    ]
  }
]
